-- Reference data: built-in life areas, goal templates, achievements and region rules.
-- Generated by tools/gen-reference-data.py, together with the English strings in packages/i18n.
-- Upserts, so the migration can be re-run safely.

on conflict (key) do update set icon = excluded.icon, color_token = excluded.color_token, sort_order = excluded.sort_order, suggested_for = excluded.suggested_for, hidden_for_teen = excluded.hidden_for_teen;

on conflict (id) do update set area_key = excluded.area_key, type = excluded.type, title_key = excluded.title_key, defaults = excluded.defaults, sort_order = excluded.sort_order, suitable_for_teen = excluded.suitable_for_teen;

on conflict (key) do update set tier = excluded.tier, icon = excluded.icon, criteria = excluded.criteria, sort_order = excluded.sort_order;

-- Digital consent ages are a starting point and must be confirmed by legal review per market.
on conflict (region) do update set digital_consent_age = excluded.digital_consent_age, teen_sharing_default = excluded.teen_sharing_default, analytics_allowed_default = excluded.analytics_allowed_default;
